// HUFRA native shell (Capacitor).
//
// The app ships its own interface (www/, generated by scripts/build-app.mjs
// during `cap sync`), so tabs open instantly and the shell works offline.
// Only data comes from the network: CAPACITOR_SERVER_URL is baked into the
// bundle as the API/photos/map-tile server (default https://hufra.pages.dev).
const config = {
  appId: 'ly.tripoli.hufra',
  appName: 'HUFRA',
  webDir: 'www',
  server: { androidScheme: 'https' },
  ios: {
    contentInset: 'never',
    backgroundColor: '#15181C',
    limitsNavigationsToAppBoundDomains: false,
  },
  plugins: {
    SplashScreen: {
      launchAutoHide: false,
      backgroundColor: '#15181C',
      showSpinner: false,
    },
    Geolocation: { enableHighAccuracy: true },
    // Capacitor 8 / Android 15+: the app is drawn edge-to-edge. The pages use
    // <meta name="viewport" content="...viewport-fit=cover"> and pad with
    // env(safe-area-inset-*) (public/static/css/tokens.css), so let Capacitor
    // pass the real insets through, and say "cover" up front to avoid a
    // layout jump at startup.
    SystemBars: { insetsHandling: 'css', initialViewportFitValueHint: 'cover' },
  },
}

export default config
